arguments.command:
cd /app; cat > tests/lag_alert_test.sh <<'EOF'
#!/bin/bash
fail=0
mkdir -p data/readings
out=$(NOW=$(( $(date -u -d "2026-11-01T00:00:00Z" +%s) + 8*3600 )) bash ops/lag-alert.sh 2>&1)
echo "$out" | grep -q '最大 6 時間' || { echo "lag-alert should say 最大 6 時間: $out"; fail=1; }
echo "$out" | grep -q '24' && { echo "lag-alert still mentions 24: $out"; fail=1; }
exit $fail
EOF
tail -2 data/readings/latest.csv; bash tests/lag_alert_test.sh

